INSERT INTO knowledge.source_claim (claim_id, claim_code, source_version_id, chapter_id, chunk_id, page_start, page_end, claim_type, claim_kind, claim_text, knowledge_type, contract, confidence, status) VALUES
   ('bb6b2dac-fb97-5cde-a274-f7ab4d66f609', 'KCR-0013', 'KUMAR_CLARK_10_2017', 'KC-C28', 'd133e703-46c8-5a26-a05b-0bd6c507b385', '955', '955', 'RESPIRATORY_METHOD', 'threshold', 'COPD is airflow limitation that is not fully reversible, usually progressive, and associated with an abnormal inflammatory response of the lungs to noxious particles or gases. It brings together emphysema, small airways disease and chronic bronchitis. Chronic bronchitis is classically a daily productive cough for 3 months per year for 2 consecutive years. Cigarette smoking accounts for over 90% of cases in developed countries; in developing countries, smoke from biomass heating fuels and cooking in poorly ventilated areas is implicated.', 'medicine', '{"what_is_it":"COPD definition + chronic bronchitis + aetiology","what_fact_produces":"COUGH_DURATION_DAYS, SMOKING_STATUS, SMOKING_PACK_YEARS, BIOMASS_EXPOSURE","source_support":"Kumar & Clark 10e p955"}'::jsonb, 0.9, 'VERIFIED'),
   ('1d246dc5-8a7d-5c36-bb06-8f4aff8e2cbd', 'KCR-0014', 'KUMAR_CLARK_10_2017', 'KC-C28', 'd133e703-46c8-5a26-a05b-0bd6c507b385', '956', '956', 'RESPIRATORY_METHOD', 'rule', 'Characteristic symptoms of COPD: productive cough with white or clear sputum, wheeze and breathlessness; patients are prone to lower respiratory tract infections. Systemic effects include hypertension, osteoporosis, depression, weight loss, reduced muscle mass, weakness and right heart failure. In severe disease the patient is tachypnoeic with prolonged expiration, uses accessory muscles, may have intercostal indrawing and pursing of the lips on expiration; chest expansion is poor, lungs hyperinflated, cricosternal distance reduced, with loss of normal cardiac and liver dullness. Hypercapnia causes peripheral vasodilation, bounding pulse, coarse flapping tremor, confusion and progressive drowsiness.', 'medicine', '{"what_is_it":"COPD clinical features + signs","what_fact_produces":"PURSED_LIPS, COUGH_PRODUCTIVITY, DYSPNOEA_PRESENT, RESP_RATE","source_support":"Kumar & Clark 10e p956"}'::jsonb, 0.9, 'VERIFIED'),
   ('b0c3d2f8-69e7-512b-bcd1-7aa73f64b94e', 'KCR-0015', 'KUMAR_CLARK_10_2017', 'KC-C28', 'd133e703-46c8-5a26-a05b-0bd6c507b385', '957', '957', 'RESPIRATORY_METHOD', 'investigation', 'COPD diagnosis is usually clinical: history of breathlessness and sputum production in a chronic smoker. Spirometry shows airflow limitation (FEV1:FVC reduced, PEFR low; usually <15% reversibility). CXR is often normal even when advanced, but classic features are over-inflation with low flat diaphragms and sometimes bullae with pruned vessels. Hb and packed cell volume may be elevated from persistent hypoxaemia (secondary polycythaemia). Blood gases determine respiratory failure. Sputum may grow Strep. pneumoniae, H. influenzae and Moraxella catarrhalis. ECG may show P pulmonale, RBBB and right ventricular hypertrophy. Measure alpha1-antitrypsin in premature disease or lifelong non-smokers.', 'medicine', '{"what_is_it":"COPD diagnosis + investigations","what_connects_to":"INV-SPIROMETRY, INV-ABG, INV-CXR, INV-FBC","source_support":"Kumar & Clark 10e p957"}'::jsonb, 0.9, 'VERIFIED'),
   ('d0a30235-d0cc-5a3a-b8ba-0c06f2014d99', 'KCR-0016', 'KUMAR_CLARK_10_2017', 'KC-C28', 'd133e703-46c8-5a26-a05b-0bd6c507b385', '957', '957', 'RESPIRATORY_METHOD', 'threshold', 'COPD airflow limitation severity (post-bronchodilator FEV1 in patients with FEV1/FVC <0.70): GOLD 1 Mild FEV1 >=80% predicted; GOLD 2 Moderate 50% <= FEV1 <80%; GOLD 3 Severe 30% <= FEV1 <50%; GOLD 4 Very severe FEV1 <30% predicted.', 'medicine', '{"what_is_it":"GOLD severity classification","what_fact_produces":"FEV1_PERCENT, FEV1_FVC_RATIO","source_support":"Kumar & Clark 10e p957 (GOLD 2016)"}'::jsonb, 0.9, 'VERIFIED'),
   ('da13744a-e1b5-51b6-9371-d2587ead8046', 'KCR-0017', 'KUMAR_CLARK_10_2017', 'KC-C28', 'd133e703-46c8-5a26-a05b-0bd6c507b385', '957', '957', 'RESPIRATORY_METHOD', 'management', 'COPD management: smoking cessation is the single most useful measure. Drug therapy: mild COPD responds to inhaled short-acting beta-2 agonist (salbutamol 200 mcg every 4-6 h); moderate/severe uses a long-acting beta-2 agonist; a regular LAMA (tiotropium) improves lung function, dyspnoea and quality of life; inhaled corticosteroids are recommended with frequent exacerbations or FEV1 <50% predicted (high-dose ICS not advised - pneumonia risk); oral corticosteroids in acute exacerbation. Prompt antibiotics shorten exacerbations and should always be given in acute episodes; home antibiotics when sputum turns yellow/green; long-term azithromycin reduces exacerbations. Mucolytics (carbocysteine) reduce sputum viscosity and exacerbations. LTOT (>=15-19 h/day) improves survival when PaO2 <7.3 kPa on air on two occasions, or PaO2 <8 kPa with secondary polycythaemia, nocturnal hypoxaemia, peripheral oedema or pulmonary hypertension. Pulmonary rehabilitation improves fatigue, dyspnoea and exercise tolerance. Pneumococcal polysaccharide vaccine once + annual influenza vaccination.', 'medicine', '{"what_is_it":"COPD drug + non-drug management","what_connects_to":"medications, LTOT, rehabilitation, vaccination","source_support":"Kumar & Clark 10e p957-958"}'::jsonb, 0.9, 'VERIFIED'),
   ('693cdfe1-9fe7-54e5-a3ee-4671a6fd1be5', 'KCR-0018', 'KUMAR_CLARK_10_2017', 'KC-C28', 'd133e703-46c8-5a26-a05b-0bd6c507b385', '959', '959', 'RESPIRATORY_METHOD', 'management', 'Acute COPD exacerbation may be precipitated by viral or bacterial infection with cough, acute bronchospasm and dyspnoea, and Type I or Type II respiratory failure. Management: assess airway, breathing and circulation; controlled oxygen via Venturi mask (initially 24%, target saturation 88-92% for those at risk of hypercapnia) with close ABG monitoring; corticosteroids, antibiotics and bronchodilators (nebulized salbutamol and ipratropium) in the acute phase; chest physiotherapy to clear retained secretions. If respiratory acidosis persists (pH <7.35 with elevated PaCO2), consider non-invasive ventilation - NIV reduces the need for intubation and lowers mortality. CXR excludes pneumothorax (chest drain) or pneumonia (antibiotics).', 'medicine', '{"what_is_it":"acute COPD exacerbation management algorithm","what_connects_to":"protocol step (acute COPD)","source_support":"Kumar & Clark 10e p959-960"}'::jsonb, 0.9, 'VERIFIED')
INSERT INTO knowledge.condition (id, concept_id, condition_code, canonical_name, description, condition_type, status) VALUES
   ('3243e22c-36ed-5b10-bf53-9d725910d14b', NULL, 'COND-COPD', 'COPD (chronic obstructive pulmonary disease)', 'Chronic airflow limitation that is not fully reversible, encompassing emphysema, small airways disease and chronic bronchitis; caused by long-term exposure to toxic particles (smoking, biomass smoke).', 'chronic', 'active'),
   ('9714d3b6-126a-58c3-8be9-f040506c4d71', NULL, 'COND-COPD-EXACERBATION', 'COPD exacerbation', 'Acute worsening of COPD with increased dyspnoea, cough and sputum, precipitated by viral or bacterial infection; may cause Type I or Type II respiratory failure.', 'acute', 'active')
