INSERT INTO knowledge.protocol_condition (id, protocol_id, condition_id, is_primary) VALUES
   ('30f3e5bf-d55e-5837-9091-ff14792bd96e', '1e6d0e50-1ae0-5a47-803b-05cfdef6dcc5', (SELECT id FROM knowledge.condition WHERE condition_code = 'COND-COPD-EXACERBATION'), true)
INSERT INTO knowledge.protocol_step (id, protocol_id, step_code, step_label, step_type, sequence_no, instruction, rationale, required) VALUES
   ('951e0ac5-054f-5adc-8219-823ca588094c', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-01', 'Confirm acute COPD exacerbation', 'eligibility', '10', 'Confirm known COPD with an acute, sustained worsening of dyspnoea, cough or sputum beyond day-to-day variation.', 'Exacerbation is precipitated by viral/bacterial infection and may progress to respiratory failure (KCR-0018).', TRUE),
   ('511f62d2-8bfc-54f5-b659-add2dafb62d7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-02', 'Assess airway, breathing and circulation', 'red_flag', '20', 'Rapid ABC assessment; detect severe distress, confusion, drowsiness, bounding pulse or flapping tremor (hypercapnia), cyanosis or cardiorespiratory arrest.', 'Airway compromise and cardiorespiratory arrest require immediate resuscitation (KCR-0018).', TRUE),
   ('3fa683a8-c69f-5e76-b4b5-7c2726ea2a01', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-03', 'Deliver controlled oxygen therapy', 'treatment', '30', 'For those at risk of hypercapnic failure use a Venturi mask (start 24%, titrate) to maintain target saturation 88-92%; monitor closely.', 'Excess oxygen in Type II failure suppresses hypoxic drive and raises PaCO2 (KCR-0018).', TRUE),
   ('f3af4211-f2cd-5111-b02c-7dbb1e034c92', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-04', 'Obtain arterial blood gas', 'investigation', '40', 'Measure ABG to classify Type I (PaO2 <8 kPa, normal/low PaCO2) vs Type II (PaO2 <8 kPa, PaCO2 >6.5 kPa) respiratory failure; check pH.', 'Respiratory acidosis (pH <7.35 with raised PaCO2) despite medical management triggers NIV consideration (KCR-0018).', TRUE),
   ('d703cf02-e945-5856-b70d-654555ddb6f7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-05', 'Start bronchodilators + corticosteroids + antibiotics', 'treatment', '50', 'Nebulized salbutamol and ipratropium; oral prednisolone 30-40 mg; prompt antibiotics (shorten exacerbation, prevent admission); home antibiotics when sputum turns yellow/green.', 'Triple therapy in the acute phase shortens the exacerbation; ICS long-term decisions wait until recovery (KCR-0017/0018).', TRUE),
   ('55478fc6-d933-5888-bedd-01ca0df77f83', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-06', 'Clear retained secretions', 'treatment', '60', 'Encourage effective cough; chest physiotherapy when clearing secretions is difficult.', 'Retained secretions worsen obstruction and gas exchange (KCR-0018).', TRUE),
   ('b1e45542-6627-55f8-88a8-7601ee5e1743', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-07', 'Image the chest', 'investigation', '70', 'CXR to exclude pneumothorax (chest drain; CT guidance if complex bullous disease) and pneumonia (antibiotics).', 'Pneumothorax and pneumonia are treatable precipitants of deterioration (KCR-0018).', TRUE),
   ('547fab8b-d9a5-55df-a598-6096fec88a32', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-08', 'Re-assess and repeat ABG', 'monitoring', '80', 'Repeat ABG at 30-60 min (or on increasing oxygen requirements/breathlessness); keep target saturation 88-92%.', 'Trends in pH/PaCO2 determine escalation to NIV (KCR-0018).', TRUE),
   ('6ef05aa4-4f5c-5010-8017-bdbd0c7f239a', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-09', 'Consider non-invasive ventilation', 'escalation', '90', 'If persistent respiratory acidosis (pH <7.35 with PaCO2 >6.5 kPa) despite medical management and clinically appropriate: start NIV; refer to senior; review and discuss ceiling of care.', 'NIV reduces the need for intubation and lowers mortality in decompensated Type II failure (KCR-0018).', TRUE),
   ('4e91092a-e774-5772-8fd7-6ebe39ed1077', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-10', 'Escalate to critical care if deteriorating', 'escalation', '100', 'If deterioration despite NIV and clinically appropriate: consider invasive ventilation; reassess ceiling of care.', 'Invasive ventilation is used only with a clear precipitating factor and reasonable overall prognosis (KCR-0018).', TRUE),
   ('6505711b-7d53-5ff1-8d5e-f10b481f0aa5', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-11', 'Plan discharge and prevention', 'education', '110', 'Smoking cessation (single most useful measure); pneumococcal vaccine + annual influenza; pulmonary rehabilitation; assess LTOT if PaO2 <7.3 kPa (or <8 kPa with polycythaemia/nocturnal hypoxaemia/oedema/pulmonary hypertension).', 'Prevention and rehabilitation improve outcomes and reduce exacerbation frequency (KCR-0017/0018).', TRUE),
   ('df125acd-419b-5620-901f-6a94552df7a4', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), 'STEP-12', 'Close the care loop', 'follow_up', '120', 'Grade GOLD severity (FEV1/FVC <0.70; FEV1 % predicted), document treatment, response, LTOT/referral plan and follow-up; consider BODE for prognosis.', 'COPD is chronic: the exacerbation episode feeds into ongoing maintenance and surveillance (KCR-0015/0016).', TRUE)
