   ('8fe5ff50-e0f8-57d7-9089-39f850503c68', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-01'), 'score', 'SCORE-GOLD', 'GOLD severity grade', 'Grade airflow limitation by post-bronchodilator FEV1 (% predicted) with FEV1/FVC <0.70', 'routine', '10'),
