   ('2d4fd947-adc1-5567-ad7c-6c3e370df2a8', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-05'), 'medicate', 'MED-IPRATROPIUM', 'Ipratropium (SAMA)', 'Nebulizer 250-500 mcg in exacerbation', 'immediate', '20'),
   ('ef656b0b-c05e-5c94-95a5-491e40debdbd', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-05'), 'medicate', 'MED-PREDNISOLONE', 'Prednisolone', '30-40 mg oral once daily 7-14 days', 'urgent', '30'),
   ('97b354f0-a39c-55c5-8b60-54deda60afc3', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-05'), 'medicate', 'MED-AMOXICILLIN', 'Antibiotic (amoxicillin)', 'Prompt antibiotics for acute episode; home antibiotics when sputum turns yellow/green', 'urgent', '40'),
   ('f89f3b00-d932-572f-a121-6899baed2c38', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-06'), 'advice', 'ADV-COPD-CLEARANCE', 'Secretions clearance', 'Effective cough + chest physiotherapy', 'urgent', '10'),
   ('95abb61c-897f-50ab-94fa-44cb255eb206', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-07'), 'investigate', 'INV-CXR', 'Chest X-ray', 'Exclude pneumothorax and pneumonia', 'urgent', '10'),
   ('b7ae4d22-bab0-5f69-894c-d79d56399951', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-08'), 'monitor', 'MON-SPO2', 'Oxygen saturation monitoring', 'Maintain target 88-92%; repeat ABG at 30-60 min', 'urgent', '10'),
   ('60b9938b-7643-56d2-890e-e2ccd4d044c7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-08'), 'investigate', 'INV-ABG', 'Arterial blood gas (repeat)', 'Repeat 30-60 min or on deterioration', 'urgent', '20'),
   ('ec59af81-a3e1-5fc9-b94a-cb853bb3dfbd', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-09'), 'refer', 'REF-NIV', 'Non-invasive ventilation', 'pH <7.35 with PaCO2 >6.5 kPa despite medical management', 'immediate', '10'),
   ('b21ac7f6-7983-5c95-8562-36798423e37b', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-09'), 'advice', 'ADV-COPD-CEILING', 'Ceiling of care discussion', 'Review and discuss ceiling of care', 'urgent', '20'),
   ('fef06a06-4bc7-5c9b-9234-dbbe7220c4fb', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-10'), 'refer', 'REF-CRITICAL-CARE', 'Critical care referral', 'Invasive ventilation if deterioration despite NIV + appropriate', 'immediate', '10'),
   ('0c3c7176-47fb-564d-bd53-0fa6250b9a9a', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-COPD-SMOKING-CESSATION', 'Smoking cessation', 'Single most useful measure; includes biomass smoke reduction', 'routine', '10'),
   ('a28d1954-52d0-5608-aa37-d379a76fb2f4', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-COPD-PULMONARY-REHAB', 'Pulmonary rehabilitation', 'Improves dyspnoea, fatigue and exercise tolerance', 'routine', '20'),
   ('adf362f1-6467-52b1-a55e-67d3477d1768', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-COPD-VACCINES', 'Pneumococcal + influenza vaccination', 'Single pneumococcal vaccine + annual influenza', 'routine', '30'),
   ('dea4f21c-de05-5d36-b1f5-d751077b73e7', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT ps.id FROM knowledge.protocol_step ps JOIN knowledge.protocol p ON p.id = ps.protocol_id WHERE p.protocol_code = 'PROT-COPD-EXACERBATION' AND ps.step_code = 'STEP-11'), 'educate', 'EDU-COPD-LTOT', 'Long-term oxygen therapy', 'Assess if PaO2 <7.3 kPa on air (or <8 kPa with polycythaemia/nocturnal hypoxaemia/oedema/pulmonary hypertension); 15-19 h/day', 'routine', '40'),
