   ('62e43267-b6e3-5b8a-baff-9a0e0e0130d5', (SELECT id FROM knowledge.protocol WHERE protocol_code = 'PROT-COPD-EXACERBATION'), (SELECT id FROM knowledge.monitoring WHERE monitoring_code = 'MON-SPO2'), 'Continuous during exacerbation; target 88-92% if hypercapnia risk (Venturi)', 'SpO2 <88% despite oxygen, or oversaturation >92% with rising PaCO2', 'Check ABG; adjust oxygen; escalate to NIV if respiratory acidosis'),
