INSERT INTO knowledge.concept (id, concept_code, concept_type, canonical_name, display_name, status) VALUES
   ('a68b77d8-9922-5815-b29a-cffc0aafb7ca', 'CNS-EDU-COPD-SMOKING-CESSATION', 'education', 'Smoking cessation for COPD', 'Smoking cessation for COPD', 'active'),
   ('3b419d7f-9d58-57e6-8413-92c47fbb27ac', 'CNS-EDU-COPD-PULMONARY-REHAB', 'education', 'Pulmonary rehabilitation', 'Pulmonary rehabilitation', 'active'),
