INSERT INTO knowledge.education (id, concept_id, education_code, title, audience, content_type, language_code, literacy_level, body, status) VALUES
   ('edf388a1-d241-5a5b-b06b-25839579d655', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-COPD-SMOKING-CESSATION'), 'EDU-COPD-SMOKING-CESSATION', 'Smoking cessation for COPD', 'patient', 'instruction', 'en', 'plain', 'Smoking cessation is the single most useful measure in COPD; it slows deterioration. Reduce biomass smoke in the home. Seek support, nicotine replacement and follow-up (KCR-0017).', 'active'),
   ('31bb0c2b-f7a7-53f5-95d5-32b88e3c8567', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-COPD-PULMONARY-REHAB'), 'EDU-COPD-PULMONARY-REHAB', 'Pulmonary rehabilitation', 'patient', 'explanation', 'en', 'plain', 'Structured exercise and education improve fatigue, dyspnoea and exercise tolerance in COPD (KCR-0017).', 'active'),
   ('b3e17f20-ccd3-5add-9a5c-fdc1d4ea469b', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-COPD-VACCINES'), 'EDU-COPD-VACCINES', 'Vaccination for COPD', 'patient', 'instruction', 'en', 'plain', 'Receive a single pneumococcal polysaccharide vaccine and annual influenza vaccination (KCR-0017).', 'active'),
   ('8da5ce51-5922-51fc-a650-494c35a44242', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-COPD-LTOT'), 'EDU-COPD-LTOT', 'Long-term oxygen therapy', 'patient', 'explanation', 'en', 'plain', 'If PaO2 <7.3 kPa on air (or <8 kPa with polycythaemia/nocturnal hypoxaemia/peripheral oedema/pulmonary hypertension), LTOT for 15-19 h/day improves survival (KCR-0017).', 'active'),
   ('93d64f2e-e818-5205-8abe-9b9e07438eb4', (SELECT id FROM knowledge.concept WHERE concept_code = 'CNS-EDU-COPD-EXACERBATION-PLAN'), 'EDU-COPD-EXACERBATION-PLAN', 'COPD exacerbation action plan', 'caregiver', 'discharge', 'en', 'plain', 'Start home antibiotics when sputum turns yellow or green; seek urgent care for increased breathlessness, confusion or drowsiness; keep short-acting bronchodilators available (KCR-0017/0018).', 'active'),
